import{_ as s,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 单元 5 复习与自测 · 第111–117课","description":"L97–L120 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 5 复习与自测 · 第111–117课","description":"L97–L120 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-05/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 5 复习与自测","summary":"L97–L120 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课","link":"/life/english/new-concept/book-1/unit-05/review-part-02"},"next":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第118–120课","link":"/life/english/new-concept/book-1/unit-05/review-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课","link":"/life/english/new-concept/book-1/unit-05/review-part-02"},"next":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第118–120课","link":"/life/english/new-concept/book-1/unit-05/review-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/review-part-03.md","filePath":"life/english/new-concept/book-1/unit-05/review-part-03.md"}'),a={name:"life/english/new-concept/book-1/unit-05/review-part-03.md"};function i(r,e,l,h,p,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-单元-5-复习与自测-·-第111–117课" tabindex="-1">第一册：英语初阶 · 单元 5 复习与自测 · 第111–117课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-5-复习与自测-·-第111–117课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 5 复习与自测 · 第111–117课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-05/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-05/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-111-·-形容词最高级" tabindex="-1">Lesson 111 · 形容词最高级 <a class="header-anchor" href="#lesson-111-·-形容词最高级" aria-label="Permalink to &quot;Lesson 111 · 形容词最高级 {#lesson-111-·-形容词最高级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This is the lightest laptop in the shop.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>写最高级：light → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lightest</p><p><strong>解析：</strong> 按本课规则判断：在明确范围内比较三者或更多对象，常用 the + 最高级。短形容词常加 est，多音节常用 most。范围可用 in + 地点/群体或 of + 复数集合，如 the cheapest of the three。good 的比较级和最高级是 better、best。highest price 不等于 best choice，应把评价维度说清楚。</p></details><p><strong>表达迁移：</strong> 围绕“从多个型号中选择最合适的”写两至三句，再读给同伴听。至少使用一次形容词最高级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This is the lightest laptop in the shop. Of the three routes, this one is the most convenient.</p><p>The lightest 为最高级，in the shop 限定比较范围；laptop 是被选中的类别名词。 Of the three routes 提供三者范围；the most convenient 是多音节形容词最高级，one 指路线。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-111">回看本课</a></p><h2 id="lesson-112-·-形容词最高级" tabindex="-1">Lesson 112 · 形容词最高级 <a class="header-anchor" href="#lesson-112-·-形容词最高级" aria-label="Permalink to &quot;Lesson 112 · 形容词最高级 {#lesson-112-·-形容词最高级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Of the three routes, this one is the most convenient.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>写最高级：convenient → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> most convenient</p><p><strong>解析：</strong> 按本课规则判断：在明确范围内比较三者或更多对象，常用 the + 最高级。短形容词常加 est，多音节常用 most。范围可用 in + 地点/群体或 of + 复数集合，如 the cheapest of the three。good 的比较级和最高级是 better、best。highest price 不等于 best choice，应把评价维度说清楚。</p></details><p><strong>表达迁移：</strong> 围绕“从多个型号中选择最合适的”写两至三句，再读给同伴听。至少使用一次形容词最高级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Of the three routes, this one is the most convenient. This is the lightest laptop in the shop.</p><p>Of the three routes 提供三者范围；the most convenient 是多音节形容词最高级，one 指路线。 The lightest 为最高级，in the shop 限定比较范围；laptop 是被选中的类别名词。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-112">回看本课</a></p><h2 id="lesson-113-·-so-neither-简短附和" tabindex="-1">Lesson 113 · so/neither 简短附和 <a class="header-anchor" href="#lesson-113-·-so-neither-简短附和" aria-label="Permalink to &quot;Lesson 113 · so/neither 简短附和 {#lesson-113-·-so-neither-简短附和}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I enjoy hiking, and so does my sister.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>补助动词：I enjoy hiking. So ___ my sister.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> does</p><p><strong>解析：</strong> 按本课规则判断：肯定附和用 So + 助动词或情态动词 + 主语，否定附和用 Neither + 助动词或情态动词 + 主语。I can swim 对应 So can I；I don&#39;t drive 对应 Neither do I。选择的助动词需匹配原句，不能全部用 am。none 表没有一个或一点，通常替代前文数量，不等于 not 这个副词。</p></details><p><strong>表达迁移：</strong> 围绕“表示双方情况相同以及数量为零”写两至三句，再读给同伴听。至少使用一次so/neither 简短附和，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I enjoy hiking, and so does my sister. I cannot skate, and neither can Tom.</p><p>第一分句 enjoy 为一般现在时；附和中的主语 my sister 为单数，因此用 so does，而不是 so do。 Cannot skate 是否定能力陈述；neither can Tom 用相同情态动词并倒装，表示汤姆也不能。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-113">回看本课</a></p><h2 id="lesson-114-·-so-neither-简短附和" tabindex="-1">Lesson 114 · so/neither 简短附和 <a class="header-anchor" href="#lesson-114-·-so-neither-简短附和" aria-label="Permalink to &quot;Lesson 114 · so/neither 简短附和 {#lesson-114-·-so-neither-简短附和}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I cannot skate, and neither can Tom.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>补助动词：I cannot skate. Neither ___ Tom.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> can</p><p><strong>解析：</strong> 按本课规则判断：肯定附和用 So + 助动词或情态动词 + 主语，否定附和用 Neither + 助动词或情态动词 + 主语。I can swim 对应 So can I；I don&#39;t drive 对应 Neither do I。选择的助动词需匹配原句，不能全部用 am。none 表没有一个或一点，通常替代前文数量，不等于 not 这个副词。</p></details><p><strong>表达迁移：</strong> 围绕“表示双方情况相同以及数量为零”写两至三句，再读给同伴听。至少使用一次so/neither 简短附和，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I cannot skate, and neither can Tom. I enjoy hiking, and so does my sister.</p><p>Cannot skate 是否定能力陈述；neither can Tom 用相同情态动词并倒装，表示汤姆也不能。 第一分句 enjoy 为一般现在时；附和中的主语 my sister 为单数，因此用 so does，而不是 so do。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-114">回看本课</a></p><h2 id="lesson-115-·-复合不定代词" tabindex="-1">Lesson 115 · 复合不定代词 <a class="header-anchor" href="#lesson-115-·-复合不定代词" aria-label="Permalink to &quot;Lesson 115 · 复合不定代词 {#lesson-115-·-复合不定代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Someone is waiting at the side door.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>填 be：Someone ___ waiting.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：someone、anyone、everyone、no one 指人，something、anything、everything、nothing 指事物。作主语时通常视作单数，后用 is/has 等。形容词修饰它们时放在后面，如 something useful。nothing 和 no one 已含否定意义，标准英语通常不再加 not。some/any 的选择仍要结合肯定、否定、请求等语境。</p></details><p><strong>表达迁移：</strong> 围绕“表达有人、无人和不确定对象”写两至三句，再读给同伴听。至少使用一次复合不定代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Someone is waiting at the side door. There is nothing unusual in the box.</p><p>Someone 作主语按单数处理，因此用 is waiting；at the side door 表等候位置。 There is 引出 nothing；unusual 放在复合不定代词之后，nothing 已含否定，无需再加 not。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-115">回看本课</a></p><h2 id="lesson-116-·-复合不定代词" tabindex="-1">Lesson 116 · 复合不定代词 <a class="header-anchor" href="#lesson-116-·-复合不定代词" aria-label="Permalink to &quot;Lesson 116 · 复合不定代词 {#lesson-116-·-复合不定代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There is nothing unusual in the box.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>排序：useful / something.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> something useful</p><p><strong>解析：</strong> 按本课规则判断：someone、anyone、everyone、no one 指人，something、anything、everything、nothing 指事物。作主语时通常视作单数，后用 is/has 等。形容词修饰它们时放在后面，如 something useful。nothing 和 no one 已含否定意义，标准英语通常不再加 not。some/any 的选择仍要结合肯定、否定、请求等语境。</p></details><p><strong>表达迁移：</strong> 围绕“表达有人、无人和不确定对象”写两至三句，再读给同伴听。至少使用一次复合不定代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There is nothing unusual in the box. Someone is waiting at the side door.</p><p>There is 引出 nothing；unusual 放在复合不定代词之后，nothing 已含否定，无需再加 not。 Someone 作主语按单数处理，因此用 is waiting；at the side door 表等候位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-116">回看本课</a></p><h2 id="lesson-117-·-过去进行时" tabindex="-1">Lesson 117 · 过去进行时 <a class="header-anchor" href="#lesson-117-·-过去进行时" aria-label="Permalink to &quot;Lesson 117 · 过去进行时 {#lesson-117-·-过去进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was making breakfast when the lights went out.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 be：I ___ making breakfast when the lights went out.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> was</p><p><strong>解析：</strong> 按本课规则判断：过去进行时由 was/were + 动词 ing 构成，常描绘过去某时的背景动作。一般过去时可表达期间发生的较短事件，如 was cooking when the phone rang。when 可以引出事件，while 常引出持续背景，但应看从句的实际意义，不能把两个词与某一种时态死绑。过去进行时不保证动作最终完成。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去某一时刻正在进行的活动”写两至三句，再读给同伴听。至少使用一次过去进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I was making breakfast when the lights went out. They were waiting outside at eight yesterday.</p><p>Was making 描写过去背景动作；when 引出的 went out 表停电事件。两者形成持续背景与突发事件的对照。 Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-117">回看本课</a></p>',60)])])}const d=s(a,[["render",i]]);export{m as __pageData,d as default};
